<script setup>
import { computed, ref, onMounted } from 'vue'
import { X, Check, ShieldCheck, ArrowRight, LockKeyhole } from 'lucide-vue-next'
import StatusBadge from './StatusBadge.vue'
import { get, identifier, money, label, date, message } from '../services/api'
const props = defineProps({ module: String, item: Object, can: Function, currentUser: Object })
const emit = defineEmits(['close','action'])
const dialog=ref(), content=ref(null), error=ref(''), busy=ref(true)
const application=computed(() => content.value?.solicitud || props.item)
onMounted(async () => {
 dialog.value.showModal()
 try {
  if(props.module==='solicitudes') content.value=await get(`/solicitudes/${identifier(props.item)}`)
  if(props.module==='cuentas') content.value=await get(`/cuentas/${identifier(props.item)}/movimientos`)
  if(props.module==='tarjetas') content.value=await get(`/tarjetas/${identifier(props.item)}/estados-cuenta`)
 } catch(e) { error.value=message(e) }
 finally { busy.value=false }
})
const transitions=computed(()=>({revision_manual:['aprobada','rechazada'],aprobada:['aceptada','cancelada'],aceptada:['en_tramite'],en_tramite:['emitida','rechazada']}[application.value.estado] || []))
const actions={aprobada:'Aprobar revisión',rechazada:'Rechazar gestión',aceptada:'Registrar aceptación',cancelada:'Cancelar gestión',en_tramite:'Iniciar trámite',emitida:'Asignar límite y emitir'}
</script>
<template><dialog ref="dialog" class="detail-dialog" @cancel.prevent="$emit('close')"><div class="dialog-heading"><div><p class="eyebrow">DETALLE DE {{ (module === 'solicitudes' ? 'Gestiones' : label(module)).toUpperCase() }}</p><h2>{{ item.folio || item.nombre || item.name || item.numero || item.referencia || label(item.action) }}</h2></div><button class="icon-button" aria-label="Cerrar detalle" @click="$emit('close')"><X :size="22"/></button></div><div class="dialog-body"><div v-if="error" class="error-box" role="alert">{{ error }}</div><p v-if="busy" class="loading">Consultando información…</p><template v-else-if="module==='solicitudes'"><div class="detail-status"><StatusBadge :value="application.estado"/><span class="muted">Versión {{ application.version }}</span></div><div class="detail-stats"><div><small>Producto solicitado</small><b>{{ label(application.producto) }}</b></div><div><small>Límite solicitado</small><b>{{ money(application.limite_solicitado_centavos) }}</b></div><div><small>Máximo de Analítica</small><b>{{ application.limite_aprobado_centavos == null ? 'Pendiente' : money(application.limite_aprobado_centavos) }}</b></div></div><div v-if="application.decision" class="notice">{{ application.decision.motivo }}<small>Referencia de CP Analítica: {{ application.decision.referencia }}</small></div><div v-if="application.estado==='en_evaluacion'" class="notice">Esperando la evaluación de CP Analítica. La emisión requiere un resultado de riesgo y la aceptación del cliente.</div><div v-if="application.resolucion" class="notice">Límite asignado por el operador: <strong>{{ money(application.limite_asignado_centavos) }}</strong><small>{{ application.resolucion.nota }}</small></div><div v-if="application.tipo==='prestamo'" class="notice">La emisión registra el crédito autorizado. El desembolso y las condiciones del préstamo requieren su propio proceso.</div><h3>Recorrido de la gestión</h3><div class="timeline"><article v-for="event in content?.historial" :key="event.id"><span class="timeline-dot"><Check :size="13"/></span><div><b>{{ label(event.estado) }}</b><p>{{ event.note }}</p><small>{{ date(event.created_at) }} · {{ event.actor }}</small></div></article></div><p class="integrity" :class="{'error-text':content?.integridad_verificada === false}"><ShieldCheck :size="17"/>{{ content?.integridad_verificada ? 'Integridad del historial verificada' : 'No se pudo verificar la integridad del historial' }}</p><div v-if="can('solicitudes.manage')" class="detail-actions"><button v-for="target in transitions" :key="target" class="primary" :class="{secondary:['rechazada','cancelada'].includes(target)}" @click="$emit('action','transicion',{...application,target})">{{ actions[target] }}<ArrowRight :size="16"/></button></div></template>
<template v-else-if="module==='cuentas'"><div class="detail-status"><StatusBadge :value="item.estado"/><strong>{{ money(item.saldo_centavos) }}</strong></div><p class="muted">{{ label(item.tipo) }} · {{ item.numero }}</p><div v-if="can('cuentas.manage')" class="detail-actions"><button class="secondary" @click="$emit('action','estado-cuenta',item)"><LockKeyhole :size="16"/>{{ item.estado==='activa'?'Bloquear cuenta':'Activar cuenta' }}</button></div><h3>Movimientos recientes</h3><div v-for="row in content?.data" :key="row.id" class="movement"><div><b>{{ row.concepto }}</b><small>{{ date(row.created_at) }}</small></div><b :class="row.importe_centavos<0?'negative':'positive'">{{ money(row.importe_centavos) }}</b></div><p v-if="!content?.data?.length" class="muted">Esta cuenta aún no tiene movimientos.</p></template>
<template v-else-if="module==='tarjetas'"><div class="detail-status"><StatusBadge :value="item.estado"/><span>•••• {{ item.ultimos_cuatro }}</span></div><div class="detail-stats"><div><small>Límite</small><b>{{ money(item.limite_centavos) }}</b></div><div><small>Capital pendiente</small><b>{{ money(item.principal_centavos) }}</b></div><div><small>Intereses</small><b>{{ money(item.interes_centavos) }}</b></div></div><div v-if="can('tarjetas.write')" class="detail-actions"><button class="primary" @click="$emit('action','consumo',item)">Registrar consumo</button><button v-if="item.tipo==='credito'" class="secondary" @click="$emit('action','pago',item)">Registrar pago</button><button class="secondary" @click="$emit('action','estado-tarjeta',item)">{{ item.estado==='activa'?'Bloquear':'Activar' }}</button></div><h3>Estados de cuenta</h3><div v-for="row in content?.data" :key="row.id" class="statement-card"><div><b>{{ row.periodo }}</b><strong>{{ money(row.saldo_centavos) }}</strong></div><p>Pago mínimo: {{ money(row.minimo_centavos) }} · Pagado al mínimo: {{ money(row.pagado_centavos) }}</p><small>Fecha de corte: {{ row.fecha_corte }} · Pagar antes de: {{ row.fecha_pago }}</small></div><p v-if="!content?.data?.length" class="muted">El estado de cuenta aparecerá al ejecutar el cierre de la fecha de corte.</p></template>
<template v-else-if="module==='planillas'"><div class="detail-status"><StatusBadge :value="item.estado"/><strong>{{ money(item.total_centavos) }}</strong></div><p v-if="item.ultimo_error" class="error-box">{{ item.ultimo_error }}</p><div v-for="(row,index) in item.pagos" :key="index" class="movement"><div><b>{{ row.nombre }}</b><small>{{ row.cuenta_id }}</small></div><b>{{ money(row.centavos) }}</b></div><p class="notice">Quien carga la planilla no puede autorizarla. Una vez autorizada, el proceso programado realizará la dispersión completa.</p><button v-if="can('planillas.approve') && item.estado==='pendiente_autorizacion' && item.creado_por!==identifier(currentUser)" class="primary" @click="$emit('action','autorizar',item)">Revisar y autorizar planilla</button><p v-else-if="item.creado_por===identifier(currentUser)" class="muted">La autorización debe realizarla otra persona.</p></template>
<template v-else><dl class="detail-list"><template v-for="(value,key) in item" :key="key"><template v-if="!['id','_id','password','updated_at'].includes(key)"><dt>{{ label(key) }}</dt><dd>{{ key.endsWith('_centavos') ? money(value) : typeof value==='object' ? JSON.stringify(value,null,2) : value }}</dd></template></template></dl><button v-if="module==='productos' && item.type!=='prestamo' && can('productos.write')" class="primary" @click="$emit('action','editar-producto',item)">Editar política del producto</button><button v-if="module==='usuarios' && can('usuarios.write') && identifier(item)!==identifier(currentUser)" class="primary" @click="$emit('action','editar-usuario',item)">Actualizar acceso</button></template></div></dialog></template>
